import React from "react";
import { useNavigate } from "react-router-dom";

const Hero = () => {
  const navigate = useNavigate();

  return (
    <section className="hero">

      <div className="container">

        {/* LEFT SIDE */}
        <div className="left">

          <p className="tag">WELCOME</p>

          <h1>
            I'm <span className="name">Swetha A</span>
          </h1>

          <h2 className="role">
            Full Stack Developer • System Thinker • Problem Solver
          </h2>

          <p className="desc">
            I enjoy building scalable systems, clean UI experiences, and real-world
            applications that solve meaningful problems through structured thinking.
          </p>

          <div className="buttons">
            <button className="btn primary" onClick={() => navigate("/projects")}>
              Explore Projects →
            </button>

            <button className="btn secondary" onClick={() => navigate("/about")}>
              About Me →
            </button>
          </div>

        </div>

        {/* RIGHT SIDE - ORBIT ANIMATION */}
        <div className="right">

          <div className="orbit">

            {/* CENTER GIRL AVATAR */}
            <div className="center">
              <img
                src="https://i.ibb.co/4f1R9Zc/female-avatar.png"
                alt="avatar"
              />
              <p>Swetha A</p>
            </div>

            {/* ORBITING CHIPS */}
            <div className="ring">

              <span className="chip">React</span>
              <span className="chip">Java</span>
              <span className="chip">Spring Boot</span>
              <span className="chip">MySQL</span>
              <span className="chip">Problem Solver</span>

            </div>

          </div>

        </div>

      </div>

      <style>{`

        .hero {
          min-height: 100vh;
          display: flex;
          align-items: center;
          background: radial-gradient(circle at top, #0b1220, #050816);
          padding: 0 8%;
        }

        .container {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 60px;
          width: 100%;
          align-items: center;
        }

        /* LEFT */
        .tag {
          font-size: 12px;
          letter-spacing: 3px;
          color: #64748b;
          margin-bottom: 15px;
        }

        h1 {
          font-size: 62px;
          margin: 0;
        }

        .name {
          color: #38BDF8;
        }

        .role {
          font-size: 20px;
          color: #94a3b8;
          margin-top: 10px;
        }

        .desc {
          margin-top: 18px;
          font-size: 16px;
          color: #cbd5e1;
          line-height: 1.7;
          max-width: 520px;
        }

        .buttons {
          margin-top: 30px;
          display: flex;
          gap: 15px;
        }

        .btn {
          padding: 12px 22px;
          border-radius: 10px;
          cursor: pointer;
          transition: 0.3s;
          font-weight: 600;
          border: 1px solid rgba(56,189,248,0.3);
        }

        .primary {
          background: #38BDF8;
          color: #0b1220;
        }

        .secondary {
          background: rgba(255,255,255,0.03);
          color: #38BDF8;
        }

        /* RIGHT ORBIT */
        .orbit {
          position: relative;
          width: 340px;
          height: 340px;
          margin: auto;
          display: flex;
          align-items: center;
          justify-content: center;
        }

        /* CENTER GIRL */
        .center {
          position: absolute;
          text-align: center;
          z-index: 2;
        }

        .center img {
          width: 90px;
          height: 90px;
          border-radius: 50%;
          border: 2px solid rgba(56,189,248,0.4);
          box-shadow: 0 0 20px rgba(56,189,248,0.15);
        }

        .center p {
          margin-top: 8px;
          font-size: 13px;
          color: #94a3b8;
        }

        /* ORBIT RING */
        .ring {
          width: 260px;
          height: 260px;
          border-radius: 50%;
          position: relative;
          animation: rotate 12s linear infinite;
        }

        /* CHIPS */
        .chip {
          position: absolute;
          padding: 8px 12px;
          border-radius: 20px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.2);
          color: #cbd5e1;
          font-size: 12px;
        }

        /* ORBIT POSITIONS */
        .chip:nth-child(1) { top: 0; left: 50%; transform: translateX(-50%); }
        .chip:nth-child(2) { top: 25%; right: 0; }
        .chip:nth-child(3) { bottom: 25%; right: 0; }
        .chip:nth-child(4) { bottom: 0; left: 50%; transform: translateX(-50%); }
        .chip:nth-child(5) { top: 50%; left: 0; transform: translateY(-50%); }

        /* ROTATION ANIMATION */
        @keyframes rotate {
          0% {
            transform: rotate(0deg);
          }
          100% {
            transform: rotate(360deg);
          }
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .container {
            grid-template-columns: 1fr;
            text-align: center;
          }

          .orbit {
            margin-top: 40px;
          }

          h1 {
            font-size: 42px;
          }
        }

      `}</style>

    </section>
  );
};

export default Hero;
